/**
 * Store AST generator: reads tools/scripts/tsc/ast.json and produces the
 * generated files of tsc/internal/ast/store (design:
 * tsc/internal/ast/docs/store-ast-design-20260922.md; the edge resolution,
 * the two layers of the binder's accessors and the Factory:
 * tsc/internal/ast/docs/store-checker-design-20260923.md 2.5 and 2.6).
 *
 * Usage: node tools/scripts/tsc/generate-go-store.ts
 *
 * Generates:
 *   - shapes_generated.go: payload words and list mask per kind, role slot tables,
 *     the binder's reserved slot tables
 *   - views_generated.go: slot constants, typed views, member and role accessors
 *   - foreach_generated.go: ForEachChild
 *   - builder_generated.go: one constructor per definition, for a source Store
 *   - factory_generated.go: New, Update and Clone per definition, for a
 *     synthetic Store (the Pointer NodeFactory's parameters)
 *   - convert/convert_generated.go: Pointer AST to Store
 *   - storetest/equivalence_generated.go: Pointer and Store compared member by member
 *
 * A member takes payload words in declaration order: a child or list is one
 * word, a text is two ([offset, length]), a bool, TokenFlags or kind is one.
 * Identifier and PrivateIdentifier keep their text in the header instead. The
 * binder's reserved slots (boundSlots) follow the members, one word each.
 */

import * as fs from "node:fs";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
import { xSync } from "tinyexec";
import type {
    MemberInfo,
    NodeType,
    Type,
} from "./schema.ts";
import { api } from "./schema.ts";

const ROOT = path.resolve(import.meta.dirname!, "../../..");
const OUT_DIR = path.join(ROOT, "tsc/internal/ast/store");
const HEADER = "// Code generated by tools/scripts/tsc/generate-go-store.ts. DO NOT EDIT.";
const AST_IMPORT = `"github.com/microsoft/TypeScript/tsc/internal/ast"`;
const STORE_IMPORT = `"github.com/microsoft/TypeScript/tsc/internal/ast/store"`;

// ────────────────────────────────────────────────────────────────────────────
// Override tables
// ────────────────────────────────────────────────────────────────────────────

// Member order for definitions whose Pointer ForEachChild is hand-written. The
// order must be the order in which that ForEachChild visits.
const memberOrderOverrides: Record<string, string[]> = {
    SourceFile: ["Statements", "EndOfFileToken"],
    // TODO(store): the Pointer version visits TypeExpression before name when
    // !IsNameFirst. A fixed shape cannot express that. Decided together with
    // where JSDoc lives (store-ast-design-20260922.md section 7).
    JSDocParameterOrPropertyTag: ["TagName", "name", "IsBracketed", "TypeExpression", "IsNameFirst", "Comment"],
};

// Kinds removed from a role table although the member exists, because the
// Pointer accessor of the same name does not return it.
const roleOverrides: Record<string, string[]> = {
    // (*ast.Node).Expression panics on these kinds.
    Expression: ["DefaultClause", "TypeParameter", "SyntheticReferenceExpression"],
    // (*ast.Node).Body reads BodyBase, which ClassStaticBlockDeclaration does not embed.
    Body: ["ClassStaticBlockDeclaration"],
    // (*ast.Node).Type has no case for JSDocVariadicType.
    Type: ["JSDocVariadicType"],
    // (*ast.Node).Text panics on JsxText.
    Text: ["JsxText"],
};

// Definitions whose single text member lives in the header (section 5 of the
// implementation instructions), not in the payload.
const headerTextDefinitions = new Set(["Identifier", "PrivateIdentifier"]);

// Roles the equivalence test compares against the Pointer method of the same
// name. Text is compared on Identifier and PrivateIdentifier as well.
const testedRoles = ["Name", "Expression", "Type", "Initializer", "Body", "Text", "Modifiers"];

// ────────────────────────────────────────────────────────────────────────────
// Schema to slots
// ────────────────────────────────────────────────────────────────────────────

type SlotClass = "child" | "list" | "text" | "bool" | "tokenFlags" | "kind" | "bound";

const slotWords: Record<SlotClass, number> = { child: 1, list: 1, text: 2, bool: 1, tokenFlags: 1, kind: 1, bound: 1 };

// The reserved slots of the binder (store-binder-design-20260922.md 2.3): the
// goOnly members that the Pointer binder writes and that are neither in the
// header (Symbol, FlowNode) nor in Bound (NextContainer). Each is one uint32
// word at the end of the payload, 0 after the parse; the binder writes it
// through the generated setter. Keyed by member name, in slot order. The word
// has two layers (A1, V1): the id layer (accessor, its Go type), which the
// binder reads and writes, and the resolving layer (the member's own name, the
// Pointer type's Store form), which asks the node's Store for the owner:
// resolve is the Store method that turns the word into the value.
const boundSlots: { name: string; accessor: string; type: string; resolved: string; resolve: string; }[] = [
    { name: "LocalSymbol", accessor: "LocalSymbolId", type: "SymbolId", resolved: "*Symbol", resolve: "symbolAt" },
    { name: "Locals", accessor: "LocalsRef", type: "uint32", resolved: "SymbolTable", resolve: "localsAt" },
    { name: "EndFlowNode", accessor: "EndFlowRef", type: "FlowRef", resolved: "Flow", resolve: "flowAt" },
    { name: "ReturnFlowNode", accessor: "ReturnFlowRef", type: "FlowRef", resolved: "Flow", resolve: "flowAt" },
    { name: "FallthroughFlowNode", accessor: "FallthroughFlowRef", type: "FlowRef", resolved: "Flow", resolve: "flowAt" },
];

function boundSlot(name: string) {
    return boundSlots.find(b => b.name === name);
}

/** The goOnly fields of every base the definition embeds, transitively. */
function baseFields(node: NodeType): MemberInfo[] {
    const fields: MemberInfo[] = [];
    const seen = new Set<NodeType>();
    const visit = (base: NodeType) => {
        if (seen.has(base)) return;
        seen.add(base);
        fields.push(...base.fields);
        for (const b of base.extends) visit(b);
    };
    for (const base of node.extends) visit(base);
    return fields;
}

interface Slot {
    member: MemberInfo;
    /** Capitalized member name: the accessor name. */
    name: string;
    class: SlotClass;
    /** First payload word. */
    word: number;
}

interface KindRef {
    name: string;
    value: number;
}

interface Definition {
    node: NodeType;
    name: string;
    kinds: KindRef[];
    slots: Slot[];
    words: number;
    /** Identifier / PrivateIdentifier: text in the header, no payload. */
    headerText: boolean;
    /** Members without a slot, as TODO comments. */
    todos: string[];
}

const problems: string[] = [];

function isPrimitive(type: Type, name: string): boolean {
    return type.kind === "primitive" && type.name === name;
}

type Classification = { slot: SlotClass; } | { header: true; } | { skip: true; } | { todo: string; };

function classify(def: NodeType, m: MemberInfo): Classification {
    if (m.isKindParam() || m.name === "Flags" || m.name === "modifierFlags") return { header: true };
    if (m.goOnly || m.noGo) return { skip: true };
    if (m.isChild()) return { slot: m.listKind ? "list" : "child" };
    const type = m.type;
    if (type.kind === "list" && type.listKind === "raw" && isPrimitive(type.elementType, "string")) {
        return { todo: `${m.name} []string has no slot: where JSDoc lives is undecided (store-ast-design-20260922.md section 5)` };
    }
    if (isPrimitive(type, "string")) {
        return headerTextDefinitions.has(def.name) ? { header: true } : { slot: "text" };
    }
    if (isPrimitive(type, "bool")) return { slot: "bool" };
    if (isPrimitive(type, "TokenFlags")) return { slot: "tokenFlags" };
    if (type.baseKind() === "kind") return { slot: "kind" };
    if (isPrimitive(type, "any")) {
        // SyntheticExpression.Type is a checker type: checker data, like the
        // goOnly members (store-ast-design-20260922.md section 5).
        return { todo: `${m.name} any has no slot: a checker type, kept in a side table` };
    }
    problems.push(`${def.name}.${m.name}: no slot class for type ${JSON.stringify(m.rawType)}`);
    return { skip: true };
}

function orderedMembers(node: NodeType): MemberInfo[] {
    const override = memberOrderOverrides[node.name];
    if (!override) return node.members;
    const listed = override.map(name => {
        const m = node.members.find(m => m.name === name);
        if (!m) problems.push(`${node.name}: override names unknown member ${name}`);
        return m!;
    });
    return [...listed, ...node.members.filter(m => !override.includes(m.name))];
}

const kindValues = new Map<string, number>();
{
    let value = 0;
    for (const element of api.kindElements()) {
        if (element.name) kindValues.set(element.name, value++);
    }
}
if (kindValues.size > 512) {
    throw new Error(`${kindValues.size} kinds do not fit the 512-entry tables`);
}

function kindRef(name: string): KindRef {
    const value = kindValues.get(name);
    if (value === undefined) throw new Error(`unknown kind ${name}`);
    return { name, value };
}

const reservedParams = new Set(["b", "kind", "flags", "pos", "end", "data", "id"]);

function buildDefinition(node: NodeType): Definition {
    const def: Definition = {
        node,
        name: node.name,
        kinds: node.allKinds().map(k => kindRef(k.name)),
        slots: [],
        words: 0,
        headerText: headerTextDefinitions.has(node.name),
        todos: [],
    };
    for (const m of orderedMembers(node)) {
        const c = classify(node, m);
        if ("todo" in c) {
            def.todos.push(c.todo);
            continue;
        }
        if (!("slot" in c)) continue;
        if (reservedParams.has(m.goParamName())) {
            problems.push(`${node.name}.${m.name}: parameter name ${m.goParamName()} is reserved in the constructor`);
        }
        def.slots.push({ member: m, name: api.capitalize(m.name), class: c.slot, word: def.words });
        def.words += slotWords[c.slot];
    }
    // The reserved slots come last, so that the child and list words and the
    // ForEachChild order are what they were. A slot is present when the
    // definition declares the member or embeds a base that declares it.
    const declared = [...node.members, ...baseFields(node)].filter(m => m.goOnly).map(m => m.name);
    for (const b of boundSlots) {
        if (!declared.includes(b.name)) continue;
        const m = node.members.find(m => m.name === b.name) ?? baseFields(node).find(m => m.name === b.name)!;
        def.slots.push({ member: m, name: b.accessor, class: "bound", word: def.words });
        def.words += slotWords.bound;
    }
    if (def.words > 16) {
        problems.push(`${node.name}: ${def.words} payload words do not fit the 16-bit list mask`);
    }
    return def;
}

const definitions = api.nodes().map(buildDefinition);

// A kind may be covered by several definitions (Token covers Identifier and
// the keywords). The one with a payload wins; two with payloads is an error.
const kindDefinition = new Map<number, Definition>();
{
    const candidates = new Map<number, Definition[]>();
    for (const def of definitions) {
        for (const kind of def.kinds) {
            candidates.set(kind.value, [...(candidates.get(kind.value) ?? []), def]);
        }
    }
    const weight = (def: Definition) => def.words * 4 + (def.headerText ? 2 : 0) + (def.node.isMultiKind() ? 0 : 1);
    for (const [value, defs] of candidates) {
        defs.sort((a, b) => weight(b) - weight(a));
        if (defs.length > 1 && (defs[1].words > 0 || defs[1].headerText)) {
            problems.push(`kind ${defs[0].kinds.find(k => k.value === value)!.name} is defined by both ${defs[0].name} and ${defs[1].name}`);
        }
        kindDefinition.set(value, defs[0]);
    }
}

if (problems.length > 0) {
    throw new Error(`cannot generate the Store:\n  ${problems.sort().join("\n  ")}`);
}

/** Kinds with a payload, in Kind order. */
const payloadKinds: { kind: KindRef; def: Definition; }[] = [];
for (const [value, def] of [...kindDefinition].sort((a, b) => a[0] - b[0])) {
    if (def.words > 0) payloadKinds.push({ kind: def.kinds.find(k => k.value === value)!, def });
}

/** Definitions that get a typed view, a constructor and a convert case. */
const viewDefinitions = definitions.filter(def => def.words > 0 || def.headerText);

/** Kinds of a definition, in the order the definition lists them. */
function goKinds(def: Definition): string {
    return def.kinds.map(k => `ast.Kind${k.name}`).join(", ");
}

function isMultiKind(def: Definition): boolean {
    return def.kinds.length > 1;
}

// ── Roles ──

type RoleClass = "child" | "list" | "text";

interface Role {
    name: string;
    class: RoleClass;
    table: string;
    /** kind value → payload word */
    slots: Map<number, number>;
}

const roles: Role[] = [];
const mixedRoles: string[] = [];
{
    const byName = new Map<string, { classes: Set<SlotClass>; defs: Set<Definition>; }>();
    for (const def of viewDefinitions) {
        for (const slot of def.slots) {
            if (slot.class !== "child" && slot.class !== "list" && slot.class !== "text") continue;
            const entry = byName.get(slot.name) ?? { classes: new Set(), defs: new Set() };
            entry.classes.add(slot.class);
            entry.defs.add(def);
            byName.set(slot.name, entry);
        }
    }
    for (const [name, { classes, defs }] of byName) {
        if (defs.size < 2) continue;
        if (classes.size > 1) {
            mixedRoles.push(`${name} (${[...defs].map(d => `${[...classes].find(c => d.slots.some(s => s.name === name && s.class === c))} in ${d.name}`).join(", ")})`);
            continue;
        }
        const role: Role = { name, class: [...classes][0] as RoleClass, table: `${api.uncapitalize(name)}Slot`, slots: new Map() };
        const excluded = new Set(roleOverrides[name] ?? []);
        for (const { kind, def } of payloadKinds) {
            if (excluded.has(kind.name)) continue;
            const slot = def.slots.find(s => s.name === name);
            if (slot) role.slots.set(kind.value, slot.word);
        }
        roles.push(role);
    }
}
for (const name of Object.keys(roleOverrides)) {
    if (!roles.some(r => r.name === name)) throw new Error(`roleOverrides names ${name}, which is not a role`);
}

function role(name: string): Role {
    const r = roles.find(r => r.name === name);
    if (!r) throw new Error(`${name} is not a role`);
    return r;
}

// ── Bound roles ──

interface BoundRole {
    name: string;
    /** The resolving accessor: the member's name. */
    resolver: string;
    resolved: string;
    resolve: string;
    type: string;
    table: string;
    /** kind value → payload word */
    slots: Map<number, number>;
}

// One role per reserved slot, whatever the number of definitions that have it.
const boundRoles: BoundRole[] = boundSlots.map(b => {
    const role: BoundRole = { name: b.accessor, resolver: b.name, resolved: b.resolved, resolve: b.resolve, type: b.type, table: `${api.uncapitalize(b.name)}Slot`, slots: new Map() };
    for (const { kind, def } of payloadKinds) {
        const slot = def.slots.find(s => s.class === "bound" && s.name === b.accessor);
        if (slot) role.slots.set(kind.value, slot.word);
    }
    return role;
});

// ────────────────────────────────────────────────────────────────────────────
// Code generation
// ────────────────────────────────────────────────────────────────────────────

class CodeWriter {
    private lines: string[] = [];

    write(line: string = "") {
        this.lines.push(line);
    }

    toString(): string {
        return this.lines.join("\n") + "\n";
    }
}

function slotConst(def: Definition, slot: Slot): string {
    // A reserved slot's constant is named after the member (Locals), not the
    // accessor (LocalsSlot).
    const name = slot.class === "bound" ? api.capitalize(slot.member.name) : slot.name;
    return `${api.uncapitalize(def.name)}${name}Slot`;
}

function goType(slot: Slot): string {
    switch (slot.class) {
        case "child":
            return "Node";
        case "list":
            return "List";
        case "text":
            return "string";
        case "bool":
            return "bool";
        case "tokenFlags":
            return "ast.TokenFlags";
        case "kind":
            return "ast.Kind";
        case "bound":
            return boundSlot(slot.member.name)!.type;
    }
}

/** Constructor parameter type. */
function paramType(slot: Slot): string {
    switch (slot.class) {
        case "child":
            return "NodeRef";
        case "list":
            return "ListRef";
        default:
            return goType(slot);
    }
}

// ── shapes_generated.go ──

function generateShapes(): string {
    const w = new CodeWriter();
    w.write(HEADER);
    w.write();
    w.write("package store");
    w.write();
    w.write(`import ${AST_IMPORT}`);
    w.write();
    w.write("type shape struct {");
    w.write("\tslots    uint8  // payload words in extra");
    w.write("\tlistMask uint16 // bit i: word i holds a list block index");
    w.write("}");
    w.write();
    w.write("var shapes = [512]shape{");
    for (const { kind, def } of payloadKinds) {
        let mask = 0;
        for (const slot of def.slots) {
            if (slot.class === "list") mask |= 1 << slot.word;
        }
        w.write(`\tast.Kind${kind.name}: {${def.words}, 0b${mask.toString(2)}},`);
    }
    w.write("}");
    w.write();
    w.write("// Payload word of the member with that role; 0xFF = the kind does not have");
    w.write("// it. A role is a child, list or text member that two or more definitions");
    w.write("// declare with the same class. Declared with different classes, so not a role:");
    for (const mixed of mixedRoles) {
        w.write(`//   - ${mixed}`);
    }
    w.write("var (");
    for (const r of roles) {
        w.write(`\t${r.table} [512]uint8`);
    }
    w.write(")");
    w.write();
    w.write("// Payload word of each reserved slot of the binder; 0xFF = the kind does not");
    w.write("// have it. The binder's role accessors (LocalsSlot, LocalSymbol, EndFlowNode,");
    w.write("// ReturnFlowNode, FallthroughFlowNode) read these.");
    w.write("var (");
    for (const b of boundRoles) {
        w.write(`\t${b.table} [512]uint8`);
    }
    w.write(")");
    w.write();
    w.write("func init() {");
    w.write(`\tfor _, t := range []*[512]uint8{${[...roles, ...boundRoles].map(r => `&${r.table}`).join(", ")}} {`);
    w.write("\t\tfor i := range t {");
    w.write("\t\t\tt[i] = 0xFF");
    w.write("\t\t}");
    w.write("\t}");
    for (const r of [...roles, ...boundRoles]) {
        for (const { kind } of payloadKinds) {
            const word = r.slots.get(kind.value);
            if (word !== undefined) w.write(`\t${r.table}[ast.Kind${kind.name}] = ${word}`);
        }
    }
    w.write("}");
    return w.toString();
}

// ── views_generated.go ──

function memberAccessor(def: Definition, slot: Slot): string {
    const index = `int(n.h.data)+${slotConst(def, slot)}`;
    switch (slot.class) {
        case "child":
            return `return n.s.node(NodeRef(n.s.extra[${index}]))`;
        case "list":
            return `return n.s.list(ListRef(n.s.extra[${index}]))`;
        case "text":
            return `return n.s.text(${index})`;
        case "bool":
            return `return n.s.extra[${index}] != 0`;
        case "tokenFlags":
            return `return ast.TokenFlags(n.s.extra[${index}])`;
        case "kind":
            return `return ast.Kind(n.s.extra[${index}])`;
        case "bound":
            return `return ${goType(slot)}(n.s.extra[${index}])`;
    }
}

function generateViews(): string {
    const w = new CodeWriter();
    w.write(HEADER);
    w.write();
    w.write("package store");
    w.write();
    w.write(`import ${AST_IMPORT}`);
    w.write();
    w.write("// A typed view is Node under another type (the same underlying struct, so the");
    w.write("// same two words and not comparable either): creating one loads nothing, and");
    w.write("// each accessor reads only its own payload word. Accessors have no nil guard");
    w.write("// (nodes[0] and list block 0 are sentinels) and no kind check outside");
    w.write("// storeChecks. A child or list word is an edge, resolved in the node's Store:");
    w.write("// a foreign edge gives the canonical Node or List (FR1, K3 in");
    w.write("// internal/ast/docs/store-checker-design-20260923.md 2.6). Slot constants");
    w.write("// are payload words in declaration order.");
    for (const def of viewDefinitions) {
        w.write();
        w.write(`// ${def.name}: ${goKinds(def)}`);
        if (def.slots.length > 0) {
            w.write("const (");
            for (const slot of def.slots) {
                const words = slot.class === "text" ? " // [offset, length]" : "";
                w.write(`\t${slotConst(def, slot)} = ${slot.word}${words}`);
            }
            w.write(")");
            w.write();
        }
        for (const todo of def.todos) {
            w.write(`// TODO(store): ${todo}.`);
        }
        w.write(`type ${def.name} Node`);
        w.write();
        w.write(`func (n Node) As${def.name}() ${def.name} {`);
        w.write("\tif storeChecks {");
        if (isMultiKind(def)) {
            w.write(`\t\tn.assertKinds("${def.name}", ${goKinds(def)})`);
        }
        else {
            w.write(`\t\tn.assertKind(${goKinds(def)})`);
        }
        w.write("\t}");
        w.write(`\treturn ${def.name}(n)`);
        w.write("}");
        if (def.headerText) {
            w.write();
            w.write(`func (n ${def.name}) Text() string { return Node(n).identifierText() }`);
        }
        for (const slot of def.slots) {
            w.write();
            w.write(`func (n ${def.name}) ${slot.name}() ${goType(slot)} { ${memberAccessor(def, slot)} }`);
            if (slot.class === "bound") {
                const b = boundSlot(slot.member.name)!;
                w.write();
                w.write(`func (n ${def.name}) Set${slot.name}(v ${goType(slot)}) {`);
                w.write("\tNode(n).checkUnsealed()");
                w.write(`\tn.s.extra[int(n.h.data)+${slotConst(def, slot)}] = uint32(v)`);
                w.write("}");
                w.write();
                w.write(`func (n ${def.name}) ${b.name}() ${b.resolved} {`);
                w.write(`\treturn n.s.${b.resolve}(n.s.extra[int(n.h.data)+${slotConst(def, slot)}])`);
                w.write("}");
            }
        }
    }

    w.write();
    w.write("// Kind-polymorphic accessors. One static table lookup picks the payload word,");
    w.write("// so the code is the same for every kind: no switch, no jump table. A kind");
    w.write("// without the role returns the nil node, the nil list or the empty string.");
    for (const r of roles) {
        // Text is hand-written in store.go: it reads the header for identifiers
        // and composes the text of kinds without a slot. It still uses textSlot.
        if (r.name === "Text") continue;
        w.write();
        const index = `int(n.h.data)+int(slot)`;
        if (r.class === "child") {
            // One resolution for both paths: a kind without the role reads the
            // edge 0 (the sentinel), so node() is expanded once and the
            // accessor stays within the inline budget.
            w.write(`func (n Node) ${r.name}() Node {`);
            w.write(`\tvar e NodeRef`);
            w.write(`\tif slot := ${r.table}[n.h.kind&511]; slot != 0xFF {`);
            w.write(`\t\te = NodeRef(n.s.extra[${index}])`);
            w.write("\t}");
            w.write("\treturn n.s.node(e)");
            w.write("}");
            continue;
        }
        w.write(`func (n Node) ${r.name}() ${r.class === "list" ? "List" : "string"} {`);
        w.write(`\tslot := ${r.table}[n.h.kind&511]`);
        w.write("\tif slot == 0xFF {");
        switch (r.class) {
            case "list":
                w.write("\t\treturn List{n.s, NoListRef}");
                break;
            case "text":
                w.write(`\t\treturn ""`);
                break;
        }
        w.write("\t}");
        switch (r.class) {
            case "child":
                w.write(`\treturn n.s.node(NodeRef(n.s.extra[${index}]))`);
                break;
            case "list":
                w.write(`\treturn n.s.list(ListRef(n.s.extra[${index}]))`);
                break;
            case "text":
                w.write(`\treturn n.s.text(${index})`);
                break;
        }
        w.write("}");
    }

    w.write();
    w.write("// The binder's role accessors, id layer: the reserved slot of the kind, or 0");
    w.write("// (and false) when the kind does not have it (one table lookup and one");
    w.write("// compare, no switch). The setter is a no-op on a kind without the slot, like");
    w.write("// the Pointer binder's setReturnFlowNode, and panics after Seal in a");
    w.write("// storeChecks build. The resolving layer has the Pointer name and reads the");
    w.write("// word in the node's owner: 0 is nil, and so is a kind without the slot.");
    for (const r of boundRoles) {
        const index = `int(n.h.data)+int(slot)`;
        w.write();
        if (r.name === "LocalsRef") {
            w.write(`func (n Node) ${r.name}() (${r.type}, bool) {`);
            w.write(`\tslot := ${r.table}[n.h.kind&511]`);
            w.write("\tif slot == 0xFF {");
            w.write("\t\treturn 0, false");
            w.write("\t}");
            w.write(`\treturn ${r.type}(n.s.extra[${index}]), true`);
            w.write("}");
        }
        else {
            w.write(`func (n Node) ${r.name}() ${r.type} {`);
            w.write(`\tslot := ${r.table}[n.h.kind&511]`);
            w.write("\tif slot == 0xFF {");
            w.write("\t\treturn 0");
            w.write("\t}");
            w.write(`\treturn ${r.type}(n.s.extra[${index}])`);
            w.write("}");
        }
        w.write();
        w.write(`func (n Node) Set${r.name}(v ${r.type}) {`);
        w.write("\tn.checkUnsealed()");
        w.write(`\tslot := ${r.table}[n.h.kind&511]`);
        w.write("\tif slot == 0xFF {");
        w.write("\t\treturn");
        w.write("\t}");
        w.write(`\tn.s.extra[${index}] = uint32(v)`);
        w.write("}");
        w.write();
        if (r.name === "LocalsRef") {
            w.write(`func (n Node) ${r.resolver}() ${r.resolved} { i, _ := n.${r.name}(); return n.s.${r.resolve}(i) }`);
        }
        else {
            w.write(`func (n Node) ${r.resolver}() ${r.resolved} { return n.s.${r.resolve}(uint32(n.${r.name}())) }`);
        }
    }
    return w.toString();
}

// ── foreach_generated.go ──

/** The walk of one slot: s and data name the Store and the payload start. */
function forEachSlot(w: CodeWriter, slot: Slot, indent: string, s: string, data: string) {
    if (slot.class === "child") {
        w.write(`${indent}if ref := NodeRef(${s}.extra[${data}+${slot.word}]); ref != NoNodeRef && v(${s}.node(ref)) { // ${slot.name}`);
        w.write(`${indent}\treturn true`);
        w.write(`${indent}}`);
        return;
    }
    // The list loop is written out, not a call: the elements are read in the
    // list's owner.
    w.write(`${indent}if at := ListRef(${s}.extra[${data}+${slot.word}]); at != NoListRef { // ${slot.name}`);
    w.write(`${indent}\tl := ${s}.list(at)`);
    w.write(`${indent}\tfor _, e := range l.edges() {`);
    w.write(`${indent}\t\tif v(l.s.node(e)) {`);
    w.write(`${indent}\t\t\treturn true`);
    w.write(`${indent}\t\t}`);
    w.write(`${indent}\t}`);
    w.write(`${indent}}`);
}

function generateForEachChild(): string {
    const w = new CodeWriter();
    w.write(HEADER);
    w.write();
    w.write("package store");
    w.write();
    w.write(`import ${AST_IMPORT}`);
    w.write();
    const walked = (def: Definition) => def.slots.filter(s => s.class === "child" || s.class === "list");
    // A definition with one child or list is walked in the switch itself; the
    // others call their function. Both follow the edges through node() and
    // list(), whose foreign side puts a function with a call over the inline
    // budget, so the switch does not rely on inlining (7d-0: the single-child
    // functions and visitList stopped inlining when node() gained the foreign
    // edges, and Walk paid a call per visit).
    const byDef = new Map<Definition, KindRef[]>();
    for (const { kind, def } of payloadKinds) {
        if (walked(def).length === 0) continue;
        byDef.set(def, [...(byDef.get(def) ?? []), kind]);
    }
    w.write("// The cases are in Kind order (of the first kind of each definition) and cover");
    w.write("// every kind that has a child or a list.");
    w.write("func (n Node) ForEachChild(v Visitor) bool {");
    w.write("\tswitch n.h.kind {");
    for (const [def, kinds] of byDef) {
        w.write(`\tcase ${kinds.map(k => `ast.Kind${k.name}`).join(", ")}:`);
        const slots = walked(def);
        if (slots.length === 1) {
            forEachSlot(w, slots[0], "\t\t", "n.s", "int(n.h.data)");
            w.write("\t\treturn false");
        }
        else {
            w.write(`\t\treturn forEachChild${def.name}(n, v)`);
        }
    }
    w.write("\t}");
    w.write("\treturn false");
    w.write("}");
    for (const def of byDef.keys()) {
        if (walked(def).length === 1) continue;
        w.write();
        w.write(`func forEachChild${def.name}(n Node, v Visitor) bool {`);
        w.write("\ts, data := n.s, int(n.h.data)");
        for (const slot of walked(def)) {
            forEachSlot(w, slot, "\t", "s", "data");
        }
        w.write("\treturn false");
        w.write("}");
    }
    return w.toString();
}

// ── builder_generated.go ──

function generateBuilder(): string {
    const w = new CodeWriter();
    w.write(HEADER);
    w.write();
    w.write("package store");
    w.write();
    w.write(`import ${AST_IMPORT}`);
    w.write();
    w.write("// One constructor per definition, parameters in payload order. Children must");
    w.write("// already exist (post-order); the constructor writes their parent. A");
    w.write("// definition with several kinds takes the kind first.");
    for (const def of viewDefinitions) {
        const params = ["flags ast.NodeFlags", "pos, end int32"];
        if (isMultiKind(def)) params.unshift("kind ast.Kind");
        if (def.headerText) params.push("text string");
        for (const slot of def.slots) {
            if (slot.class === "bound") continue;
            params.push(`${slot.member.goParamName()} ${paramType(slot)}`);
        }
        const kind = isMultiKind(def) ? "kind" : goKinds(def);
        w.write();
        w.write(`func (b *Builder) New${def.name}(${params.join(", ")}) NodeRef {`);
        if (def.headerText) {
            w.write(`\treturn b.header(${kind}, flags, 0, pos, end, b.identifierData(end, text))`);
            w.write("}");
            continue;
        }
        const words: string[] = [];
        for (const slot of def.slots) {
            const p = slot.member.goParamName();
            switch (slot.class) {
                case "child":
                    words.push(`uint32(${p})`);
                    break;
                case "list":
                    words.push(`uint32(${p})`);
                    break;
                case "text":
                    w.write(`\t${p}Off, ${p}Len := b.textWords(end, ${p})`);
                    words.push(`${p}Off`, `${p}Len`);
                    break;
                case "bool":
                    words.push(`boolWord(${p})`);
                    break;
                case "tokenFlags":
                case "kind":
                    words.push(`uint32(${p})`);
                    break;
                case "bound":
                    words.push("0");
                    break;
            }
        }
        w.write("\tdata := uint32(len(b.s.extra))");
        w.write(`\tb.s.extra = append(b.s.extra, ${words.join(", ")})`);
        const modifiers = def.slots.find(s => s.name === "Modifiers" && s.class === "list");
        const mod = modifiers ? `b.modifierFlags(${modifiers.member.goParamName()})` : "0";
        const children = def.slots.filter(s => s.class === "child" || s.class === "list");
        if (children.length === 0) {
            w.write(`\treturn b.header(${kind}, flags, ${mod}, pos, end, data)`);
            w.write("}");
            continue;
        }
        w.write(`\tid := b.header(${kind}, flags, ${mod}, pos, end, data)`);
        for (const slot of children) {
            const p = slot.member.goParamName();
            w.write(`\tb.${slot.class === "child" ? "adopt" : "adoptList"}(${p}, id)`);
        }
        w.write("\treturn id");
        w.write("}");
    }
    return w.toString();
}

// ── factory_generated.go ──

// The Factory takes the Pointer NodeFactory's parameters: the schema members
// without noFactory, in schema order, a child as Node, a list (node, modifier
// or raw) as List, and the rest by value. A member without a slot in the Store
// (a []string of JSDoc, SyntheticExpression.Type) has no parameter: its
// definition says so in a TODO.

function isNodeFlagsParam(m: MemberInfo): boolean {
    return m.type.kind === "primitive" && m.type.name === "NodeFlags";
}

interface FactoryParam {
    member: MemberInfo;
    name: string;
    type: string;
    /** The slot the member fills, if any. */
    slot?: Slot;
    kind?: true;
    flags?: true;
    headerText?: true;
}

const factoryLocals = new Set(["f", "r", "dst", "data", "node"]);

function factoryParams(def: Definition): FactoryParam[] {
    const params: FactoryParam[] = [];
    for (const m of def.node.members) {
        if (m.noFactory) continue;
        const name = m.goParamName();
        if (factoryLocals.has(name)) problems.push(`${def.name}.${m.name}: parameter name ${name} is reserved in the Factory`);
        if (m.isKindParam()) {
            params.push({ member: m, name, type: "ast.Kind", kind: true });
            continue;
        }
        if (isNodeFlagsParam(m)) {
            params.push({ member: m, name, type: "ast.NodeFlags", flags: true });
            continue;
        }
        if (def.headerText && isPrimitive(m.type, "string")) {
            params.push({ member: m, name, type: "string", headerText: true });
            continue;
        }
        const slot = def.slots.find(s => s.member === m);
        if (!slot) continue; // a TODO member: no slot, no parameter
        params.push({ member: m, name, type: goType(slot), slot });
    }
    return params;
}

function goBitmask(mask: string): string {
    return `ast.${mask}`;
}

/** New for one kind of the definition: kindExpr is the kind parameter or constant. */
function writeFactoryNew(w: CodeWriter, def: Definition, funcName: string, kindExpr: string) {
    const params = factoryParams(def);
    w.write();
    w.write(`func (f *Factory) ${funcName}(${params.map(p => `${p.name} ${p.type}`).join(", ")}) Node {`);
    const flagsParam = params.find(p => p.flags);
    const flags = !flagsParam ? "0" : flagsParam.member.bitmask ? `${flagsParam.name}&${goBitmask(flagsParam.member.bitmask)}` : flagsParam.name;
    if (def.headerText) {
        const text = params.find(p => p.headerText)!;
        w.write("\tdst := f.row()");
        w.write(`\treturn f.newNode(dst, ${kindExpr}, ${flags}, 0, f.identifierData(dst, ${text.name}))`);
        w.write("}");
        return;
    }
    if (def.words === 0) {
        w.write(`\treturn f.newNode(f.row(), ${kindExpr}, ${flags}, 0, 0)`);
        w.write("}");
        return;
    }
    w.write("\tdst := f.row()");
    const words: string[] = [];
    const byMember = new Map(params.filter(p => p.slot).map(p => [p.slot!.member, p]));
    if (def.slots.some(s => s.class === "child" || s.class === "list")) w.write("\tr := f.region");
    for (const slot of def.slots) {
        const p = byMember.get(slot.member);
        if (!p) {
            // A reserved slot of the binder, or a member without a factory
            // parameter: 0, the nil value.
            words.push(slot.class === "text" ? "textInTexts, 0" : "0");
            continue;
        }
        switch (slot.class) {
            case "child":
                words.push(`uint32(r.edge(dst, ${p.name}))`);
                break;
            case "list":
                words.push(`uint32(r.listEdge(dst, ${p.name}))`);
                break;
            case "text":
                w.write(`\t${p.name}Off, ${p.name}Len := f.text(dst, ${p.name})`);
                words.push(`${p.name}Off`, `${p.name}Len`);
                break;
            case "bool":
                words.push(`boolWord(${p.name})`);
                break;
            case "tokenFlags":
                words.push(p.member.bitmask ? `uint32(${p.name}&${goBitmask(p.member.bitmask)})` : `uint32(${p.name})`);
                break;
            case "kind":
                words.push(`uint32(${p.name})`);
                break;
            case "bound":
                words.push("0");
                break;
        }
    }
    const modifiers = def.slots.find(s => s.name === "Modifiers" && s.class === "list");
    const modParam = modifiers ? byMember.get(modifiers.member) : undefined;
    const mod = modParam ? `modifierFlags(${modParam.name})` : "0";
    w.write("\tdata := uint32(len(dst.extra))");
    w.write(`\tdst.extra = append(dst.extra, ${words.join(", ")})`);
    w.write(`\treturn f.newNode(dst, ${kindExpr}, ${flags}, ${mod}, data)`);
    w.write("}");
}

/** The view type of a definition, or Node for one without a view. */
function viewType(def: Definition): string {
    return viewDefinitions.includes(def) ? def.name : "Node";
}

/** The value of a parameter's member read from node (a view of the definition). */
function readParam(def: Definition, p: FactoryParam): string {
    if (p.kind) return "Node(node).Kind()";
    if (p.flags) return "Node(node).Flags()";
    if (p.headerText) return "node.Text()";
    return `node.${p.slot!.name}()`;
}

/** Calls New for the kind of node: a switch when the definition has kind aliases. */
function writeNewForKind(w: CodeWriter, def: Definition, args: string, wrap: (call: string) => string, what: string) {
    const aliases = def.node.kindAliases;
    if (aliases.length === 0) {
        w.write(`\treturn ${wrap(`f.New${def.name}(${args})`)}`);
        return;
    }
    w.write("\tswitch Node(node).Kind() {");
    w.write(`\tcase ast.Kind${def.node.syntaxKindName}:`);
    w.write(`\t\treturn ${wrap(`f.New${def.name}(${args})`)}`);
    for (const alias of aliases) {
        w.write(`\tcase ast.Kind${alias}:`);
        w.write(`\t\treturn ${wrap(`f.New${alias}(${args})`)}`);
    }
    w.write("\t}");
    w.write(`\tpanic("unexpected kind in ${what}: " + Node(node).Kind().String())`);
}

function writeFactoryUpdate(w: CodeWriter, def: Definition) {
    const params = factoryParams(def);
    const members = params.filter(p => !p.kind);
    // As the Pointer generator: no Update without a child member.
    if (members.length === 0 || !def.node.members.some(m => !m.noFactory && m.isChild())) return;
    const view = viewType(def);
    w.write();
    w.write(`func (f *Factory) Update${def.name}(node ${view}, ${members.map(p => `${p.name} ${p.type}`).join(", ")}) Node {`);
    const comparisons = members.map(p => {
        if (p.flags) return `${p.name} != Node(node).Flags()`;
        switch (p.slot?.class) {
            case "child":
                return `!SameNode(${p.name}, node.${p.slot.name}())`;
            case "list":
                return `!SameList(${p.name}, node.${p.slot.name}())`;
            default:
                return `${p.name} != ${readParam(def, p)}`;
        }
    });
    w.write(`\tif ${comparisons.join(" || ")} {`);
    const args = params.map(p => p.kind ? "Node(node).Kind()" : p.name).join(", ");
    const inner = new CodeWriter();
    writeNewForKind(inner, def, args, call => `f.updateNode(${call}, Node(node))`, `Update${def.name}`);
    for (const line of inner.toString().trimEnd().split("\n")) w.write(`\t${line}`);
    w.write("\t}");
    w.write("\treturn Node(node)");
    w.write("}");
}

function writeFactoryClone(w: CodeWriter, def: Definition) {
    const params = factoryParams(def);
    w.write();
    w.write(`func (f *Factory) Clone${def.name}(node ${viewType(def)}) Node {`);
    const args = params.map(p => readParam(def, p)).join(", ");
    writeNewForKind(w, def, args, call => `f.cloneNode(${call}, Node(node))`, `${def.name}.Clone`);
    w.write("}");
}

function generateFactory(): string {
    const w = new CodeWriter();
    w.write(HEADER);
    w.write();
    w.write("package store");
    w.write();
    w.write(`import ${AST_IMPORT}`);
    w.write();
    w.write("// New, Update and Clone of ast.NodeFactory per definition, for a synthetic");
    w.write("// Store (factory.go). New picks the Store once, writes the payload, the");
    w.write("// foreign entries and the header, then calls the hook; it never writes the");
    w.write("// parent of a child (invariant 18). Update compares with SameNode and");
    w.write("// SameList and returns the original when nothing changed. Clone is shallow:");
    w.write("// it shares the children and lists, and takes the flags and range but not");
    w.write("// the parent, flow, symbol or locals. internal/ast/docs/");
    w.write("// store-checker-design-20260923.md 2.6 (R, K3) and");
    w.write("// store-checker-execution-design-20260924.md 1, 4.");
    for (const def of definitions) {
        for (const todo of def.todos) {
            w.write();
            w.write(`// TODO(store): ${def.name}: ${todo}; it is not a parameter.`);
        }
        const kindParam = factoryParams(def).find(p => p.kind);
        writeFactoryNew(w, def, `New${def.name}`, kindParam ? kindParam.name : `ast.Kind${def.node.syntaxKindName}`);
        for (const alias of def.node.kindAliases) {
            writeFactoryNew(w, def, `New${alias}`, kindParam ? kindParam.name : `ast.Kind${alias}`);
        }
        writeFactoryUpdate(w, def);
        writeFactoryClone(w, def);
    }
    w.write();
    w.write("// CloneNode is (*ast.Node).Clone: Clone of the definition of the node's kind.");
    w.write("func (f *Factory) CloneNode(node Node) Node {");
    w.write("\tswitch node.Kind() {");
    const byDef = new Map<Definition, number[]>();
    for (const [value, def] of [...kindDefinition].sort((a, b) => a[0] - b[0])) {
        byDef.set(def, [...(byDef.get(def) ?? []), value]);
    }
    const kindName = (def: Definition, value: number) => def.kinds.find(k => k.value === value)!.name;
    for (const [def, values] of byDef) {
        if (values.every(v => kindName(def, v) === "Unknown")) continue;
        const kinds = values.filter(v => kindName(def, v) !== "Unknown").map(v => `ast.Kind${kindName(def, v)}`);
        w.write(`\tcase ${kinds.join(", ")}:`);
        w.write(`\t\treturn f.Clone${def.name}(${viewDefinitions.includes(def) ? `node.As${def.name}()` : "node"})`);
    }
    w.write("\t}");
    w.write(`\tpanic("store: CloneNode of " + node.Kind().String())`);
    w.write("}");
    return w.toString();
}

// ── convert/convert_generated.go ──

/** Go expression reading the member of the typed Pointer struct v. */
function pointerRead(v: string, slot: Slot): string {
    const m = slot.member;
    return m.private ? `${v}.${slot.name}()` : `${v}.${m.name}`;
}

function convertArg(slot: Slot): string {
    const read = pointerRead("d", slot);
    switch (slot.class) {
        case "child":
            return `c.node(${read})`;
        case "list":
            switch (slot.member.listKind) {
                case "ModifierList":
                    return `c.modifiers(${read})`;
                case "raw":
                    return `c.raw(${read})`;
                default:
                    return `c.list(${read})`;
            }
        case "kind":
            return `ast.Kind(${read})`;
        default:
            return read;
    }
}

function generateConvert(): string {
    const w = new CodeWriter();
    w.write(HEADER);
    w.write();
    w.write("package convert");
    w.write();
    w.write("import (");
    w.write(`\t${AST_IMPORT}`);
    w.write(`\t${STORE_IMPORT}`);
    w.write(")");
    w.write();
    w.write("// Convert builds a Store from a Pointer AST in post-order. It follows exactly");
    w.write("// the children that the Pointer ForEachChild visits, so JSDoc is not converted.");
    w.write("func Convert(file *ast.SourceFile, fileIndex uint32) *store.Store {");
    w.write("\tc := &converter{b: store.NewBuilder(file.Text(), nil, store.StoreID(fileIndex))}");
    w.write("\tc.node(file.AsNode())");
    w.write("\treturn c.b.Finish()");
    w.write("}");
    w.write();
    w.write("type converter struct {");
    w.write("\tb     *store.Builder");
    w.write("\telems []store.NodeRef // stack of the elements of the lists under construction");
    w.write("}");
    w.write();
    w.write("func (c *converter) elements(pos, end int32, nodes []*ast.Node) store.ListRef {");
    w.write("\tmark := len(c.elems)");
    w.write("\tfor _, n := range nodes {");
    w.write("\t\tc.elems = append(c.elems, c.node(n))");
    w.write("\t}");
    w.write("\tat := c.b.List(pos, end, c.elems[mark:])");
    w.write("\tc.elems = c.elems[:mark]");
    w.write("\treturn at");
    w.write("}");
    w.write();
    w.write("func (c *converter) list(l *ast.NodeList) store.ListRef {");
    w.write("\tif l == nil {");
    w.write("\t\treturn store.NoListRef");
    w.write("\t}");
    w.write("\treturn c.elements(int32(l.Pos()), int32(l.End()), l.Nodes)");
    w.write("}");
    w.write();
    w.write("func (c *converter) modifiers(l *ast.ModifierList) store.ListRef {");
    w.write("\tif l == nil {");
    w.write("\t\treturn store.NoListRef");
    w.write("\t}");
    w.write("\treturn c.list(&l.NodeList)");
    w.write("}");
    w.write();
    w.write("// A raw list has no Loc of its own.");
    w.write("func (c *converter) raw(nodes []*ast.Node) store.ListRef {");
    w.write("\tif nodes == nil {");
    w.write("\t\treturn store.NoListRef");
    w.write("\t}");
    w.write("\treturn c.elements(0, 0, nodes)");
    w.write("}");
    w.write();
    w.write("// node converts in post-order: the arguments of a constructor are evaluated");
    w.write("// left to right, so the children exist, in member order, before their parent.");
    w.write("func (c *converter) node(n *ast.Node) store.NodeRef {");
    w.write("\tif n == nil {");
    w.write("\t\treturn store.NoNodeRef");
    w.write("\t}");
    w.write("\tpos, end := int32(n.Pos()), int32(n.End())");
    w.write("\tswitch n.Kind {");
    for (const def of viewDefinitions) {
        w.write(`\tcase ${goKinds(def)}:`);
        w.write(`\t\td := n.As${def.name}()`);
        const args = ["n.Flags", "pos", "end"];
        if (isMultiKind(def)) args.unshift("n.Kind");
        for (const slot of def.slots) {
            if (slot.class !== "bound") args.push(convertArg(slot));
        }
        if (def.headerText) args.push("d.Text");
        w.write(`\t\treturn c.b.New${def.name}(${args.join(", ")})`);
    }
    w.write("\t}");
    w.write("\treturn c.b.NewToken(n.Kind, n.Flags, pos, end)");
    w.write("}");
    return w.toString();
}

// ── storetest/equivalence_generated.go ──

function generateEquivalenceTest(): string {
    const w = new CodeWriter();
    let members = 0;
    let roleChecks = 0;
    w.write(HEADER);
    w.write();
    w.write("package storetest");
    w.write();
    w.write("import (");
    w.write(`\t${AST_IMPORT}`);
    w.write(`\t${STORE_IMPORT}`);
    w.write(")");
    w.write();
    w.write("// compareMembers compares every member of the definition of p.Kind through the");
    w.write("// typed view: a child by kind and position, a list by length, position and");
    w.write("// elements, a text by value, a bool, TokenFlags or kind by value.");
    w.write("func compareMembers(m *comparer, p *ast.Node, n store.Node) {");
    w.write("\tswitch p.Kind {");
    for (const def of viewDefinitions) {
        w.write(`\tcase ${goKinds(def)}:`);
        w.write(`\t\tpv, sv := p.As${def.name}(), n.As${def.name}()`);
        if (def.headerText) {
            w.write(`\t\tif pv.Text != sv.Text() {`);
            w.write(`\t\t\tm.add(p, "${def.name}.Text")`);
            w.write("\t\t}");
            members++;
        }
        for (const slot of def.slots) {
            // A reserved slot is 0 after the parse and the Pointer field is
            // nil; the binder's equivalence test compares them.
            if (slot.class === "bound") continue;
            const label = `"${def.name}.${slot.name}"`;
            const read = pointerRead("pv", slot);
            members++;
            switch (slot.class) {
                case "child":
                    w.write(`\t\tm.node(${label}, p, ${read}, sv.${slot.name}())`);
                    break;
                case "list":
                    switch (slot.member.listKind) {
                        case "ModifierList":
                            w.write(`\t\tm.modifiers(${label}, p, ${read}, sv.${slot.name}())`);
                            break;
                        case "raw":
                            w.write(`\t\tm.raw(${label}, p, ${read}, sv.${slot.name}())`);
                            break;
                        default:
                            w.write(`\t\tm.list(${label}, p, ${read}, sv.${slot.name}())`);
                    }
                    break;
                case "kind":
                    w.write(`\t\tif ast.Kind(${read}) != sv.${slot.name}() {`);
                    w.write(`\t\t\tm.add(p, ${label})`);
                    w.write("\t\t}");
                    break;
                default:
                    w.write(`\t\tif ${read} != sv.${slot.name}() {`);
                    w.write(`\t\t\tm.add(p, ${label})`);
                    w.write("\t\t}");
            }
        }
    }
    w.write("\t}");
    w.write("}");
    w.write();
    w.write("// compareRoles compares the role accessors with the Pointer methods of the same");
    w.write("// name, on the kinds whose role table is not 0xFF. A Pointer method that panics");
    w.write("// on a kind is reported by guard and belongs in the generator's roleOverrides.");
    w.write("func compareRoles(m *comparer, p *ast.Node, n store.Node) {");
    w.write("\tswitch p.Kind {");
    for (const { kind, def } of [...payloadKinds, ...definitions.filter(d => d.headerText).map(d => ({ kind: d.kinds[0], def: d }))]) {
        const lines: string[] = [];
        for (const name of testedRoles) {
            const r = role(name);
            const present = r.slots.has(kind.value) || (name === "Text" && def.headerText);
            if (!present) continue;
            roleChecks++;
            const label = `"${name}"`;
            switch (name) {
                case "Text":
                    lines.push(`\t\tm.guard(p, ${label}, func() {`, `\t\t\tif p.Text() != n.Text() {`, `\t\t\t\tm.add(p, ${label})`, "\t\t\t}", "\t\t})");
                    break;
                case "Modifiers":
                    lines.push(`\t\tm.guard(p, ${label}, func() { m.modifiers(${label}, p, p.Modifiers(), n.Modifiers()) })`);
                    break;
                default:
                    lines.push(`\t\tm.guard(p, ${label}, func() { m.node(${label}, p, p.${name}(), n.${name}()) })`);
            }
        }
        if (lines.length === 0) continue;
        w.write(`\tcase ast.Kind${kind.name}:`);
        for (const line of lines) w.write(line);
    }
    w.write("\t}");
    w.write("}");
    w.write();
    w.write("// Comparisons per node kind, for the verification report.");
    w.write("const (");
    w.write(`\tComparedMembers = ${members}`);
    w.write(`\tComparedRoles   = ${roleChecks}`);
    w.write(")");
    return w.toString();
}

// ────────────────────────────────────────────────────────────────────────────
// Write output
// ────────────────────────────────────────────────────────────────────────────

function writeAndFormat(filePath: string, content: string) {
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, content);
    xSync("dprint", ["fmt", filePath], {
        throwOnError: true,
        nodeOptions: { stdio: "inherit", cwd: ROOT },
    });
    console.log(`Wrote ${filePath}`);
}

export default function main() {
    console.log("Generating Go Store AST code...");
    writeAndFormat(path.join(OUT_DIR, "shapes_generated.go"), generateShapes());
    writeAndFormat(path.join(OUT_DIR, "views_generated.go"), generateViews());
    writeAndFormat(path.join(OUT_DIR, "foreach_generated.go"), generateForEachChild());
    writeAndFormat(path.join(OUT_DIR, "builder_generated.go"), generateBuilder());
    writeAndFormat(path.join(OUT_DIR, "factory_generated.go"), generateFactory());
    writeAndFormat(path.join(OUT_DIR, "convert/convert_generated.go"), generateConvert());
    writeAndFormat(path.join(OUT_DIR, "storetest/equivalence_generated.go"), generateEquivalenceTest());
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
    main();
}
